actionJson:
{
  "id": "20spo-search-001-query",
  "brandColor": "#007ee5",
  "icon": "https://conn-afd-prod-endpoint-bmc9bqahasf3grgk.b01.azurefd.net/v1.0.1769/1.0.1769.4352/sharepointonline/icon.png",
  "isTrigger": false,
  "operationName": "search-query",
  "operationDefinition": {
    "type": "OpenApiConnection",
    "inputs": {
      "host": {
        "connectionName": "shared_sharepointonline",
        "operationId": "HttpRequest",
        "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
      },
      "parameters": {
        "dataset": "{{SITE_URL}}",
        "parameters/method": "POST",
        "parameters/uri": "_api/search/postquery",
        "parameters/headers": {
          "Accept": "application/json;odata=nometadata",
          "Content-Type": "application/json;odata=nometadata"
        },
        "parameters/body": "{\n  \"request\": {\n    \"Querytext\": \"{{QUERY_TEXT}}\",\n    \"RowLimit\": {{ROW_LIMIT}},\n    \"StartRow\": {{START_ROW}},\n    \"SelectProperties\": @{split('{{SELECT_PROPERTIES}}', ',')},\n    \"TrimDuplicates\": false\n  }\n}"
      },
      "authentication": {
        "type": "Raw",
        "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
      }
    },
    "runAfter": {},
    "description": "Runs a SharePoint Search (KQL) query, e.g. FileType:docx or Title:\"R&D\". SELECT_PROPERTIES is comma-separated, e.g. Title,Path. Use START_ROW with ROW_LIMIT for paging.",
    "metadata": {
      "operationMetadataId": "a1b2c3d4-0062-4000-8000-000000000001"
    }
  }
}
